var r=[{title:`Hur intervaller fungerar`,text:`Ett arbetsintervall höjer din andning och arbetsbelastning, och återhämtningsintervallet låter dig återhämta dig delvis eller till stor del. Du kan justera båda. Intervaller kan vara aeroba, som rask promenad som varvas med lugn promenad, eller hårdare, som en snabb cykelinsats följd av lätt trampande.`},{title:`Börja under maximal ansträngning`,text:`Om du är ny på träning kan du varva en minut rask promenad med två minuters bekväm promenad i sex omgångar. En erfaren löpare kan använda snabbare insatser med längre vila. Rätt arbetsfart beror på din nivå och övningen, så ett tidsförhållande ensamt säger inte hur hårt arbetet är för din kropp.`},{title:`Återhämtningens längd beror på målet`,text:`Längre återhämtning håller fart och rörelsekvalitet hög vid intensiva repetitioner. Kortare återhämtning gör passet mer kontinuerligt och kan höja den totala belastningen på hjärta och lungor, men om den är för kort sjunker kvaliteten snabbt. Ställ in arbete och vila så att de passar det konditionsmål du har i åtanke.`},{title:`Kontrollera den totala belastningen`,text:`Värm alltid upp gradvis och avsluta med något lättare. Bygg upp den totala mängden intervallarbete innan du gör intervallerna mycket hårdare. Om din gångteknik, löpmekanik eller hopprepskoordination börjar brytas ner, ta längre återhämtning, sänk intensiteten eller avsluta passet.`},{title:`Så använder du TrainUp`,text:`Vilotimern och hålltimern håller dina intervaller i tid, och efter passet skattar du passets ansträngning från 1 till 10. Hårdare är inte automatiskt bättre. När du skapar ditt program på nytt blir det lättare om 2 av dina senaste 3 pass var mycket tuffa (RPE 9 eller mer) eller mindre än 60 % genomförda, och ett steg svårare bara om de senaste 4 var lätta och fullständiga. Om du behöver mindre stötar fungerar cykling eller snabb marsch också som intervaller.`}];var a=[{label:`ACE: utforma högintensiva intervaller`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`CDC: mäta aktivitetsintensitet och pratprovet`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`CDC: rekommendationer om fysisk aktivitet för vuxna`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var n={sections:r,sources:a};export{n as default,r as sections,a as sources};